begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'telecom_basics', 'ระบบสื่อสารโทรคมนาคมพื้นฐาน (Telecommunication Systems)', 15
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'telecom_basics'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สัญญาณอนาล็อก (Analog Signal) และสัญญาณดิจิทัล (Digital Signal) แตกต่างกันอย่างไรในลักษณะพื้นฐาน', 'สัญญาณอนาล็อกมีค่าต่อเนื่อง (Continuous) เปลี่ยนแปลงได้ทุกค่าตามเวลา ในขณะที่สัญญาณดิจิทัลมีค่าไม่ต่อเนื่อง (Discrete) แสดงเป็นระดับค่าจำกัดจำนวน โดยทั่วไปมักใช้เพียงสองระดับคือ 0 และ 1 ในระบบเลขฐานสอง', 'สัญญาณดิจิทัลมีข้อได้เปรียบด้านความทนทานต่อสัญญาณรบกวนมากกว่าอนาล็อก เพราะสามารถตัดสินค่าที่ถูกต้องได้ง่ายแม้มีสัญญาณรบกวนปนอยู่บ้าง ต่างจากสัญญาณอนาล็อกที่ความคลาดเคลื่อนจากสัญญาณรบกวนจะสะสมและบิดเบือนข้อมูลได้ง่ายกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สัญญาณอนาล็อก (Analog Signal) และสัญญาณดิจิทัล (Digital Signal) แตกต่างกันอย่างไรในลักษณะพื้นฐาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การมอดูเลต (Modulation) ในระบบสื่อสารมีวัตถุประสงค์หลักอะไร', 'เป็นกระบวนการเปลี่ยนแปลงคุณลักษณะของสัญญาณพาหะ (Carrier Signal) ความถี่สูง ตามข้อมูลที่ต้องการส่ง (Message Signal) เพื่อให้สามารถส่งสัญญาณข้อมูลผ่านตัวกลางการสื่อสารในระยะไกลได้อย่างมีประสิทธิภาพ และช่วยให้สามารถส่งสัญญาณหลายช่องพร้อมกันโดยใช้ความถี่พาหะที่ต่างกัน', 'หากไม่มีการมอดูเลต สัญญาณข้อมูลความถี่ต่ำ เช่น เสียงพูด จะไม่สามารถส่งผ่านอากาศเป็นระยะทางไกลได้อย่างมีประสิทธิภาพ เนื่องจากต้องใช้สายอากาศขนาดใหญ่มากเมื่อเทียบกับความยาวคลื่นของสัญญาณความถี่ต่ำ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การมอดูเลต (Modulation) ในระบบสื่อสารมีวัตถุประสงค์หลักอะไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การมอดูเลตแบบ Amplitude Modulation (AM) และ Frequency Modulation (FM) แตกต่างกันอย่างไรในหลักการพื้นฐาน', 'AM เปลี่ยนแปลงขนาดของสัญญาณพาหะตามสัญญาณข้อมูล โดยความถี่ของสัญญาณพาหะยังคงที่ ส่วน FM เปลี่ยนแปลงความถี่ของสัญญาณพาหะตามสัญญาณข้อมูล โดยขนาดของสัญญาณพาหะยังคงที่', 'FM มีความทนทานต่อสัญญาณรบกวนดีกว่า AM มาก เนื่องจากสัญญาณรบกวนส่วนใหญ่มักปรากฏเป็นการเปลี่ยนแปลงขนาดสัญญาณ ซึ่งไม่ส่งผลกระทบต่อข้อมูลที่เข้ารหัสอยู่ในความถี่ของสัญญาณ FM มากเท่ากับที่ส่งผลต่อสัญญาณ AM', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การมอดูเลตแบบ Amplitude Modulation (AM) และ Frequency Modulation (FM) แตกต่างกันอย่างไรในหลักการพื้นฐาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การมอดูเลตแบบดิจิทัล (Digital Modulation) เช่น ASK, FSK, PSK แตกต่างจากการมอดูเลตแบบอนาล็อกอย่างไรในหลักการพื้นฐาน', 'การมอดูเลตแบบดิจิทัลเปลี่ยนแปลงคุณลักษณะของสัญญาณพาหะ (ขนาด ความถี่ หรือเฟส) ตามข้อมูลดิจิทัลที่เป็นค่าไม่ต่อเนื่อง (0 หรือ 1) แทนที่จะเป็นสัญญาณต่อเนื่องเหมือนการมอดูเลตแบบอนาล็อก โดย ASK เปลี่ยนขนาด FSK เปลี่ยนความถี่ และ PSK เปลี่ยนเฟสของสัญญาณพาหะตามบิตข้อมูล', 'ระบบสื่อสารสมัยใหม่ส่วนใหญ่ใช้การมอดูเลตแบบดิจิทัลหรือแบบผสมที่ซับซ้อนกว่า เช่น QAM (Quadrature Amplitude Modulation) ที่ผสมผสานการเปลี่ยนทั้งขนาดและเฟสพร้อมกัน เพื่อเพิ่มอัตราการส่งข้อมูลต่อหน่วยแบนด์วิดท์ให้สูงขึ้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การมอดูเลตแบบดิจิทัล (Digital Modulation) เช่น ASK, FSK, PSK แตกต่างจากการมอดูเลตแบบอนาล็อกอย่างไรในหลักการพื้นฐาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แบนด์วิดท์ (Bandwidth) ในระบบสื่อสารมีความหมายอย่างไร และมีความสำคัญต่อการส่งข้อมูลอย่างไร', 'หมายถึงช่วงความถี่ที่ระบบสื่อสารสามารถรองรับได้ในการส่งสัญญาณ ยิ่งมีแบนด์วิดท์กว้างมากเท่าใด ยิ่งสามารถส่งข้อมูลได้ในอัตราที่สูงขึ้นเท่านั้น ตามความสัมพันธ์ทางทฤษฎีระหว่างแบนด์วิดท์และความจุของช่องสัญญาณ', 'การจัดสรรแบนด์วิดท์ที่จำกัดในระบบสื่อสารต่างๆ เช่น คลื่นวิทยุ เป็นประเด็นสำคัญที่หน่วยงานกำกับดูแลด้านโทรคมนาคมต้องบริหารจัดการ เพื่อป้องกันการรบกวนกันระหว่างผู้ใช้งานความถี่ต่างๆ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แบนด์วิดท์ (Bandwidth) ในระบบสื่อสารมีความหมายอย่างไร และมีความสำคัญต่อการส่งข้อมูลอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ทฤษฎีบทของแชนนอน (Shannon''s Theorem) หรือ Shannon Capacity อธิบายความสัมพันธ์ระหว่างสิ่งใดในระบบสื่อสาร', 'อธิบายความสัมพันธ์ระหว่างความจุสูงสุดของช่องสัญญาณในการส่งข้อมูล (Channel Capacity) กับแบนด์วิดท์ของช่องสัญญาณและอัตราส่วนสัญญาณต่อสัญญาณรบกวน (Signal-to-Noise Ratio) โดยระบุว่าความจุสูงสุดที่ส่งข้อมูลได้อย่างปราศจากความผิดพลาดแปรผันตรงกับทั้งแบนด์วิดท์และลอการิทึมของอัตราส่วนสัญญาณต่อสัญญาณรบกวน', 'ทฤษฎีบทนี้เป็นพื้นฐานสำคัญของทฤษฎีสารสนเทศ ที่ใช้กำหนดขีดจำกัดทางทฤษฎีของความเร็วในการส่งข้อมูลที่เป็นไปได้ภายใต้เงื่อนไขของช่องสัญญาณหนึ่งๆ ซึ่งเป็นแนวทางในการออกแบบระบบสื่อสารให้เข้าใกล้ขีดจำกัดทางทฤษฎีนี้ให้มากที่สุด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ทฤษฎีบทของแชนนอน (Shannon''s Theorem) หรือ Shannon Capacity อธิบายความสัมพันธ์ระหว่างสิ่งใดในระบบสื่อสาร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'อัตราส่วนสัญญาณต่อสัญญาณรบกวน (Signal-to-Noise Ratio, SNR) มีผลต่อคุณภาพการสื่อสารอย่างไร', 'SNR ที่สูงหมายความว่าสัญญาณข้อมูลมีความเข้มมากกว่าสัญญาณรบกวนอย่างมีนัยสำคัญ ทำให้ผู้รับสามารถแยกแยะและถอดรหัสข้อมูลได้อย่างถูกต้องแม่นยำ ในขณะที่ SNR ต่ำหมายความว่าสัญญาณรบกวนมีความเข้มใกล้เคียงกับสัญญาณข้อมูล ทำให้เกิดความผิดพลาดในการรับส่งข้อมูลได้ง่ายขึ้น', 'การปรับปรุง SNR ทำได้หลายวิธี เช่น การเพิ่มกำลังส่งสัญญาณ การลดระยะทางการส่ง หรือการใช้เทคนิคการเข้ารหัสที่ทนทานต่อสัญญาณรบกวนมากขึ้น ซึ่งเป็นข้อพิจารณาสำคัญในการออกแบบระบบสื่อสารทุกประเภท', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'อัตราส่วนสัญญาณต่อสัญญาณรบกวน (Signal-to-Noise Ratio, SNR) มีผลต่อคุณภาพการสื่อสารอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การมัลติเพล็กซ์แบบแบ่งความถี่ (Frequency Division Multiplexing, FDM) มีหลักการทำงานอย่างไร', 'แบ่งแบนด์วิดท์ที่มีอยู่ทั้งหมดออกเป็นช่วงความถี่ย่อยหลายช่วง โดยแต่ละสัญญาณข้อมูลถูกมอดูเลตด้วยความถี่พาหะที่แตกต่างกันในแต่ละช่วง ทำให้สามารถส่งสัญญาณหลายช่องทางพร้อมกันได้ในตัวกลางเดียวกัน โดยที่แต่ละสัญญาณไม่รบกวนกันเนื่องจากอยู่ในช่วงความถี่ที่แยกจากกัน', 'FDM เป็นเทคนิคดั้งเดิมที่ใช้ในระบบสื่อสารอนาล็อก เช่น การกระจายเสียงวิทยุ ที่แต่ละสถานีใช้ความถี่พาหะที่แตกต่างกันเพื่อไม่ให้สัญญาณรบกวนกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การมัลติเพล็กซ์แบบแบ่งความถี่ (Frequency Division Multiplexing, FDM) มีหลักการทำงานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การมัลติเพล็กซ์แบบแบ่งเวลา (Time Division Multiplexing, TDM) แตกต่างจาก FDM อย่างไร', 'TDM แบ่งช่วงเวลาการส่งข้อมูลออกเป็นช่วงเวลาย่อย (Time Slot) โดยแต่ละสัญญาณข้อมูลจะได้รับการจัดสรรช่วงเวลาเฉพาะของตนในการส่งผ่านช่องสัญญาณเดียวกัน สลับกันไปตามลำดับอย่างรวดเร็ว แทนที่จะแบ่งตามความถี่เหมือน FDM', 'TDM เป็นเทคนิคที่นิยมใช้ในระบบสื่อสารดิจิทัล เช่น ระบบโทรศัพท์ดิจิทัลและเครือข่ายข้อมูล เนื่องจากสามารถจัดการและควบคุมได้ง่ายกว่าด้วยเทคโนโลยีดิจิทัลสมัยใหม่ และสามารถปรับเปลี่ยนการจัดสรรช่วงเวลาได้อย่างยืดหยุ่นตามความต้องการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การมัลติเพล็กซ์แบบแบ่งเวลา (Time Division Multiplexing, TDM) แตกต่างจาก FDM อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การลดทอนสัญญาณ (Attenuation) ในสายส่งสัญญาณโทรคมนาคมเกิดขึ้นได้อย่างไร และมีผลต่อระยะทางการส่งสัญญาณอย่างไร', 'เกิดจากการสูญเสียพลังงานของสัญญาณขณะเดินทางผ่านตัวกลาง เช่น ความต้านทานของสายทองแดงหรือการดูดกลืนแสงในเส้นใยแก้วนำแสง ทำให้ความแรงของสัญญาณลดลงตามระยะทางที่เพิ่มขึ้น หากลดทอนมากเกินไป สัญญาณที่ปลายทางอาจอ่อนเกินกว่าที่อุปกรณ์รับจะตรวจจับและถอดรหัสได้อย่างถูกต้อง', 'ระยะทางสูงสุดที่สามารถส่งสัญญาณได้อย่างมีคุณภาพจึงถูกจำกัดด้วยอัตราการลดทอนของตัวกลางที่ใช้ ซึ่งเป็นเหตุผลที่ต้องมีเครื่องขยายสัญญาณ (Repeater) ติดตั้งเป็นระยะในระบบสื่อสารระยะไกล เพื่อฟื้นฟูความแรงของสัญญาณก่อนที่จะอ่อนเกินไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การลดทอนสัญญาณ (Attenuation) ในสายส่งสัญญาณโทรคมนาคมเกิดขึ้นได้อย่างไร และมีผลต่อระยะทางการส่งสัญญาณอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เส้นใยแก้วนำแสง (Optical Fiber) ส่งสัญญาณข้อมูลด้วยหลักการใด', 'ส่งสัญญาณในรูปของแสง โดยอาศัยหลักการสะท้อนกลับหมดภายใน (Total Internal Reflection) ที่แสงเดินทางภายในแกนกลางของเส้นใย (Core) ซึ่งมีดัชนีหักเหสูงกว่าเปลือกหุ้ม (Cladding) โดยรอบ ทำให้แสงสะท้อนกลับเข้าไปในแกนกลางตลอดเส้นทางแทนที่จะทะลุออกไปด้านนอก', 'การส่งสัญญาณด้วยแสงผ่านเส้นใยแก้วนำแสงมีข้อได้เปรียบสำคัญคือมีการลดทอนสัญญาณต่ำกว่าสายทองแดงมาก ทำให้สามารถส่งสัญญาณระยะไกลได้โดยไม่ต้องมีเครื่องขยายสัญญาณบ่อยเท่า และไม่ได้รับผลกระทบจากสัญญาณรบกวนทางแม่เหล็กไฟฟ้าเหมือนสายทองแดง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เส้นใยแก้วนำแสง (Optical Fiber) ส่งสัญญาณข้อมูลด้วยหลักการใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เส้นใยแก้วนำแสงชนิด Single Mode และ Multi Mode แตกต่างกันอย่างไร และเหมาะกับการใช้งานลักษณะใด', 'เส้นใยแบบ Single Mode มีแกนกลางขนาดเล็กมาก ทำให้แสงเดินทางได้เพียงเส้นทางเดียว ลดปัญหาการกระจายตัวของสัญญาณ (Dispersion) เหมาะกับการส่งสัญญาณระยะไกลด้วยอัตราข้อมูลสูง ส่วนเส้นใยแบบ Multi Mode มีแกนกลางขนาดใหญ่กว่า ทำให้แสงเดินทางได้หลายเส้นทางพร้อมกัน มีต้นทุนอุปกรณ์ที่เชื่อมต่อต่ำกว่าแต่มีระยะทางการส่งที่จำกัดกว่า', 'Single Mode จึงนิยมใช้ในสายส่งหลักระยะไกล เช่น ระบบสื่อสารระหว่างเมืองหรือระหว่างประเทศ ในขณะที่ Multi Mode มักใช้ในระบบเครือข่ายภายในอาคารหรือระยะทางสั้นที่ต้นทุนอุปกรณ์เป็นปัจจัยสำคัญกว่าระยะทางการส่ง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เส้นใยแก้วนำแสงชนิด Single Mode และ Multi Mode แตกต่างกันอย่างไร และเหมาะกับการใช้งานลักษณะใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การกระจายตัวของสัญญาณ (Dispersion) ในเส้นใยแก้วนำแสงคืออะไร และมีผลกระทบต่อคุณภาพสัญญาณอย่างไร', 'คือปรากฏการณ์ที่พัลส์แสงที่ส่งเข้าไปในเส้นใยแก้วนำแสงขยายตัวกว้างขึ้นเมื่อเดินทางไปตามความยาวของเส้นใย เนื่องจากส่วนประกอบต่างๆ ของสัญญาณเดินทางด้วยความเร็วที่แตกต่างกันเล็กน้อย หากการกระจายตัวมากเกินไป พัลส์ที่อยู่ติดกันอาจเหลื่อมทับกันจนผู้รับไม่สามารถแยกแยะบิตข้อมูลแต่ละบิตได้อย่างถูกต้อง', 'การเลือกใช้เส้นใยแก้วนำแสงชนิด Single Mode สำหรับระยะทางไกลเป็นวิธีหนึ่งในการลดปัญหาการกระจายตัว เนื่องจากมีเส้นทางเดินทางของแสงเพียงเส้นทางเดียว ลดความแตกต่างของเวลาเดินทางระหว่างส่วนประกอบต่างๆ ของสัญญาณ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การกระจายตัวของสัญญาณ (Dispersion) ในเส้นใยแก้วนำแสงคืออะไร และมีผลกระทบต่อคุณภาพสัญญาณอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบชุมสายโทรศัพท์ส่วนบุคคล (Private Automatic Branch Exchange, PABX) มีหน้าที่อะไรในอาคารสำนักงาน', 'ทำหน้าที่เป็นชุมสายโทรศัพท์ภายในองค์กร จัดการการโทรระหว่างเบอร์โทรศัพท์ภายในอาคารเดียวกัน และเชื่อมต่อกับระบบโทรศัพท์สาธารณะภายนอกผ่านสายเชื่อมโยงจำนวนจำกัด ทำให้พนักงานสามารถโทรหากันภายในองค์กรได้โดยไม่ต้องผ่านระบบโทรศัพท์สาธารณะภายนอก และแบ่งปันสายเชื่อมโยงภายนอกร่วมกันได้อย่างมีประสิทธิภาพ', 'ระบบ PABX สมัยใหม่มักพัฒนาเป็นระบบดิจิทัลหรือใช้เทคโนโลยี IP (IP-PBX) ที่รองรับทั้งการสื่อสารด้วยเสียงและข้อมูลผ่านเครือข่ายเดียวกัน ให้ความยืดหยุ่นและฟังก์ชันเพิ่มเติมมากกว่าระบบชุมสายแบบดั้งเดิม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบชุมสายโทรศัพท์ส่วนบุคคล (Private Automatic Branch Exchange, PABX) มีหน้าที่อะไรในอาคารสำนักงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบเครือข่ายโทรศัพท์สาธารณะแบบสลับวงจร (Public Switched Telephone Network, PSTN) ทำงานตามหลักการใด', 'ใช้หลักการสลับวงจร (Circuit Switching) โดยเมื่อมีการโทรออก ระบบจะสร้างเส้นทางการเชื่อมต่อเฉพาะระหว่างผู้โทรและผู้รับสายตลอดระยะเวลาการสนทนา เส้นทางนี้จะถูกจองไว้เฉพาะสำหรับการสนทนานั้นจนกว่าจะวางสาย ต่างจากระบบสลับแพ็กเก็ต (Packet Switching) ที่แบ่งข้อมูลเป็นชิ้นเล็กๆ ส่งผ่านเส้นทางที่อาจแตกต่างกันในแต่ละครั้ง', 'ระบบ PSTN แบบดั้งเดิมมีข้อจำกัดด้านการใช้ทรัพยากรเครือข่ายที่ไม่ยืดหยุ่น เนื่องจากเส้นทางถูกจองไว้เฉพาะแม้ในช่วงที่ไม่มีการพูดคุย ซึ่งเป็นเหตุผลสำคัญที่ระบบสื่อสารสมัยใหม่หันไปใช้เทคโนโลยีแบบสลับแพ็กเก็ตแทน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบเครือข่ายโทรศัพท์สาธารณะแบบสลับวงจร (Public Switched Telephone Network, PSTN) ทำงานตามหลักการใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เทคโนโลยี VoIP (Voice over Internet Protocol) แตกต่างจากระบบโทรศัพท์แบบดั้งเดิมอย่างไร', 'VoIP แปลงสัญญาณเสียงให้เป็นข้อมูลดิจิทัล แล้วส่งผ่านเครือข่ายอินเทอร์เน็ตหรือเครือข่ายข้อมูลในรูปแบบแพ็กเก็ต (Packet Switching) แทนที่จะใช้วงจรเฉพาะแบบระบบโทรศัพท์ดั้งเดิม (Circuit Switching) ทำให้สามารถใช้โครงสร้างพื้นฐานเครือข่ายข้อมูลที่มีอยู่แล้วร่วมกันสำหรับทั้งเสียงและข้อมูล ลดต้นทุนโครงสร้างพื้นฐานที่ต้องแยกกันสำหรับแต่ละประเภทการสื่อสาร', 'อย่างไรก็ตาม คุณภาพของการสนทนาผ่าน VoIP ขึ้นอยู่กับคุณภาพของเครือข่ายข้อมูลที่ใช้ เช่น ความหน่วงเวลา (Latency) และการสูญหายของแพ็กเก็ต (Packet Loss) ซึ่งเป็นปัจจัยที่ต้องบริหารจัดการอย่างเหมาะสมเพื่อรักษาคุณภาพเสียงให้ดี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เทคโนโลยี VoIP (Voice over Internet Protocol) แตกต่างจากระบบโทรศัพท์แบบดั้งเดิมอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การตรวจจับและแก้ไขข้อผิดพลาด (Error Detection and Correction) ในระบบสื่อสารดิจิทัลมีความจำเป็นอย่างไร', 'เพราะสัญญาณรบกวนและการลดทอนระหว่างการส่งอาจทำให้ข้อมูลบางบิตเปลี่ยนแปลงไปจากที่ส่งจริง เทคนิคการตรวจจับข้อผิดพลาด เช่น Parity Check หรือ Cyclic Redundancy Check (CRC) ช่วยให้ผู้รับสามารถทราบได้ว่าข้อมูลที่ได้รับมีความผิดพลาดหรือไม่ ในขณะที่เทคนิคการแก้ไขข้อผิดพลาด เช่น Forward Error Correction (FEC) ช่วยให้ผู้รับสามารถแก้ไขข้อผิดพลาดบางประเภทได้โดยไม่ต้องขอให้ส่งข้อมูลซ้ำ', 'การเลือกใช้เทคนิคที่เหมาะสมขึ้นอยู่กับลักษณะของระบบสื่อสาร เช่น ระบบที่มีความล่าช้าสูงในการส่งซ้ำ (เช่น การสื่อสารผ่านดาวเทียม) มักนิยมใช้ FEC เพื่อลดความจำเป็นในการขอส่งข้อมูลซ้ำ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การตรวจจับและแก้ไขข้อผิดพลาด (Error Detection and Correction) ในระบบสื่อสารดิจิทัลมีความจำเป็นอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'อัตราส่วนบิตข้อมูลผิดพลาด (Bit Error Rate, BER) ใช้เป็นดัชนีวัดคุณภาพของระบบสื่อสารอย่างไร', 'คืออัตราส่วนของจำนวนบิตที่ได้รับผิดพลาดต่อจำนวนบิตทั้งหมดที่ส่ง ค่า BER ที่ต่ำแสดงว่าระบบสื่อสารมีคุณภาพดี ส่งข้อมูลได้อย่างแม่นยำ ในขณะที่ค่า BER ที่สูงบ่งชี้ถึงปัญหาในระบบสื่อสาร เช่น สัญญาณรบกวนสูงหรือคุณภาพสัญญาณไม่ดี', 'การวัดค่า BER เป็นวิธีมาตรฐานในการประเมินและเปรียบเทียบประสิทธิภาพของระบบสื่อสารต่างๆ รวมถึงใช้ในการตรวจสอบและวินิจฉัยปัญหาของระบบสื่อสารที่ติดตั้งใช้งานอยู่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'อัตราส่วนบิตข้อมูลผิดพลาด (Bit Error Rate, BER) ใช้เป็นดัชนีวัดคุณภาพของระบบสื่อสารอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดระบบสื่อสารดิจิทัลจึงมักใช้เทคนิคการบีบอัดข้อมูล (Data Compression) ก่อนการส่งสัญญาณ', 'เพื่อลดปริมาณข้อมูลที่ต้องส่งจริง ทำให้ใช้แบนด์วิดท์น้อยลงสำหรับข้อมูลปริมาณเท่าเดิม หรือสามารถส่งข้อมูลได้มากขึ้นภายในแบนด์วิดท์ที่มีจำกัด ซึ่งช่วยเพิ่มประสิทธิภาพการใช้ทรัพยากรเครือข่ายที่มีต้นทุนสูง', 'การบีบอัดข้อมูลแบ่งเป็นแบบไม่สูญเสียข้อมูล (Lossless) ที่สามารถคืนข้อมูลกลับสู่สภาพเดิมได้ครบถ้วน และแบบสูญเสียข้อมูลบางส่วน (Lossy) ที่ยอมให้สูญเสียรายละเอียดบางส่วนที่ไม่สำคัญมากเพื่อแลกกับอัตราการบีบอัดที่สูงขึ้น เช่น การบีบอัดสัญญาณเสียงหรือวิดีโอ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดระบบสื่อสารดิจิทัลจึงมักใช้เทคนิคการบีบอัดข้อมูล (Data Compression) ก่อนการส่งสัญญาณ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ความหน่วงเวลาในการสื่อสาร (Latency) มีผลกระทบต่อคุณภาพการใช้งานประเภทใดเป็นพิเศษ', 'มีผลกระทบมากเป็นพิเศษต่อการสื่อสารแบบเรียลไทม์ เช่น การสนทนาด้วยเสียงหรือวิดีโอ ที่ผู้ใช้งานต้องการการตอบสนองที่ทันทีทันใด ความหน่วงเวลาที่มากเกินไปทำให้เกิดความล่าช้าในการสนทนาที่รู้สึกได้ ก่อให้เกิดความรำคาญและความเข้าใจผิดในระหว่างการสื่อสาร', 'ระบบสื่อสารที่ใช้เส้นทางระยะทางไกลมาก เช่น การสื่อสารผ่านดาวเทียมวงโคจรค้างฟ้า มักมีความหน่วงเวลาที่สูงกว่าระบบสื่อสารภาคพื้นดินระยะใกล้อย่างมีนัยสำคัญ เนื่องจากระยะทางที่สัญญาณต้องเดินทางไกลกว่ามาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ความหน่วงเวลาในการสื่อสาร (Latency) มีผลกระทบต่อคุณภาพการใช้งานประเภทใดเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดระบบสื่อสารสมัยใหม่จึงมักออกแบบให้มีการเข้ารหัสข้อมูล (Encryption) เพื่อความปลอดภัยของข้อมูล', 'เพราะข้อมูลที่ส่งผ่านช่องทางสื่อสารสาธารณะมีความเสี่ยงที่จะถูกดักฟังหรือเข้าถึงโดยบุคคลที่ไม่ได้รับอนุญาต การเข้ารหัสแปลงข้อมูลให้อยู่ในรูปแบบที่ไม่สามารถอ่านหรือเข้าใจได้หากไม่มีกุญแจถอดรหัสที่ถูกต้อง ช่วยปกป้องความลับและความถูกต้องของข้อมูลระหว่างการส่ง', 'ความสำคัญของการเข้ารหัสเพิ่มขึ้นอย่างมากในยุคที่ข้อมูลสำคัญ เช่น ข้อมูลทางการเงินหรือข้อมูลส่วนบุคคล ถูกส่งผ่านเครือข่ายสาธารณะเป็นจำนวนมาก ทำให้เทคนิคการเข้ารหัสกลายเป็นส่วนพื้นฐานสำคัญของระบบสื่อสารสมัยใหม่แทบทุกประเภท', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดระบบสื่อสารสมัยใหม่จึงมักออกแบบให้มีการเข้ารหัสข้อมูล (Encryption) เพื่อความปลอดภัยของข้อมูล'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การขยายสัญญาณด้วยเครื่องทวนสัญญาณ (Repeater) และตัวขยายสัญญาณ (Amplifier) แตกต่างกันอย่างไรในหลักการทำงาน', 'Repeater รับสัญญาณที่อ่อนลง ถอดรหัสข้อมูลออกมา แล้วสร้างสัญญาณใหม่ที่มีคุณภาพเทียบเท่าสัญญาณต้นฉบับส่งต่อไป ซึ่งช่วยกำจัดสัญญาณรบกวนที่สะสมมาด้วย ส่วน Amplifier เพียงแค่ขยายความแรงของสัญญาณเดิมที่รับเข้ามาโดยตรง โดยไม่ได้ถอดรหัสหรือสร้างสัญญาณใหม่ ทำให้สัญญาณรบกวนที่ปนอยู่เดิมก็ถูกขยายไปพร้อมกับสัญญาณข้อมูลด้วย', 'ในระบบสื่อสารดิจิทัลระยะไกล การใช้ Repeater จึงให้คุณภาพสัญญาณที่ดีกว่าการใช้ Amplifier เพียงอย่างเดียว เนื่องจาก Repeater สามารถฟื้นฟูสัญญาณให้กลับมามีคุณภาพใกล้เคียงต้นฉบับ ในขณะที่ Amplifier เพียงขยายทั้งสัญญาณและสัญญาณรบกวนไปพร้อมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การขยายสัญญาณด้วยเครื่องทวนสัญญาณ (Repeater) และตัวขยายสัญญาณ (Amplifier) แตกต่างกันอย่างไรในหลักการทำงาน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดระบบโทรคมนาคมจึงต้องมีมาตรฐานสากลที่กำหนดโดยองค์กรระหว่างประเทศ เช่น ITU (International Telecommunication Union)', 'เพื่อให้อุปกรณ์และระบบสื่อสารจากผู้ผลิตและประเทศต่างๆ สามารถทำงานร่วมกันได้ (Interoperability) และเพื่อบริหารจัดการทรัพยากรที่มีจำกัดร่วมกัน เช่น คลื่นความถี่วิทยุและตำแหน่งวงโคจรดาวเทียม ซึ่งเป็นทรัพยากรที่ต้องประสานงานกันในระดับนานาชาติเพื่อป้องกันการรบกวนกันข้ามพรมแดน', 'หากไม่มีมาตรฐานสากลที่เป็นที่ยอมรับร่วมกัน การสื่อสารระหว่างประเทศหรือระหว่างระบบที่ใช้เทคโนโลยีต่างกันจะเป็นไปได้ยากมาก และอาจเกิดปัญหาการรบกวนกันของคลื่นความถี่ที่ใช้งานทับซ้อนกันโดยไม่มีการประสานงาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดระบบโทรคมนาคมจึงต้องมีมาตรฐานสากลที่กำหนดโดยองค์กรระหว่างประเทศ เช่น ITU (International Telecommunication Union)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดสายทองแดงแบบคู่บิดเกลียว (Twisted Pair Cable) จึงมีการบิดเกลียวสายทั้งสองเส้นเข้าด้วยกันแทนที่จะเดินสายขนานกันตรงๆ', 'การบิดเกลียวช่วยลดผลกระทบจากสัญญาณรบกวนแม่เหล็กไฟฟ้าจากภายนอก (Electromagnetic Interference) โดยทำให้สัญญาณรบกวนที่เหนี่ยวนำเข้าสู่สายทั้งสองเส้นมีขนาดใกล้เคียงกันและหักล้างกันเมื่อพิจารณาผลต่างของสัญญาณระหว่างสายทั้งสอง ซึ่งเป็นหลักการที่เรียกว่า Common Mode Rejection', 'ความถี่และจำนวนรอบการบิดเกลียวต่อความยาวที่แตกต่างกัน มีผลต่อความสามารถในการต้านทานสัญญาณรบกวนและแบนด์วิดท์ที่รองรับได้ ซึ่งเป็นเหตุผลที่สายเคเบิลประเภทต่างๆ ถูกจำแนกเป็นระดับคุณภาพ (Category) ที่แตกต่างกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดสายทองแดงแบบคู่บิดเกลียว (Twisted Pair Cable) จึงมีการบิดเกลียวสายทั้งสองเส้นเข้าด้วยกันแทนที่จะเดินสายขนานกันตรงๆ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเชื่อมต่อระบบสื่อสารในพื้นที่ที่มีสัญญาณรบกวนทางแม่เหล็กไฟฟ้าสูง เช่น ใกล้อุปกรณ์ไฟฟ้ากำลัง จึงมักแนะนำให้ใช้เส้นใยแก้วนำแสงแทนสายทองแดง', 'เพราะเส้นใยแก้วนำแสงส่งสัญญาณในรูปของแสงผ่านตัวกลางที่เป็นฉนวน ไม่ได้รับผลกระทบจากสนามแม่เหล็กไฟฟ้าเลย ต่างจากสายทองแดงที่เป็นตัวนำไฟฟ้าและมีความเสี่ยงที่จะถูกเหนี่ยวนำสัญญาณรบกวนจากสนามแม่เหล็กไฟฟ้าของอุปกรณ์กำลังไฟฟ้าที่อยู่ใกล้เคียง', 'ด้วยเหตุนี้ในโรงงานอุตสาหกรรมหรือสถานีไฟฟ้าที่มีอุปกรณ์กำลังไฟฟ้าขนาดใหญ่ทำงานอยู่ใกล้เคียง จึงมักเลือกใช้เส้นใยแก้วนำแสงสำหรับระบบสื่อสารและควบคุม แทนสายทองแดงที่อาจได้รับผลกระทบจากสัญญาณรบกวนได้ง่ายกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเชื่อมต่อระบบสื่อสารในพื้นที่ที่มีสัญญาณรบกวนทางแม่เหล็กไฟฟ้าสูง เช่น ใกล้อุปกรณ์ไฟฟ้ากำลัง จึงมักแนะนำให้ใช้เส้นใยแก้วนำแสงแทนสายทองแดง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบสื่อสารโทรคมนาคมจึงต้องพิจารณาความซ้ำซ้อนของเส้นทาง (Route Diversity) สำหรับการเชื่อมต่อที่สำคัญ', 'เพื่อให้มั่นใจว่าหากเส้นทางหลักเกิดความเสียหาย เช่น สายเคเบิลถูกตัดขาดโดยอุบัติเหตุระหว่างการขุดถนน ยังคงมีเส้นทางสำรองที่แยกจากเส้นทางหลักอย่างชัดเจนสามารถรักษาการเชื่อมต่อไว้ได้ ไม่ให้การสื่อสารขาดหายไปทั้งหมด', 'การออกแบบเส้นทางสำรองที่แท้จริงต้องหลีกเลี่ยงการเดินสายทั้งสองเส้นทางผ่านจุดเดียวกัน (Common Point of Failure) เช่น ท่อร้อยสายเดียวกันหรือเสาสัญญาณต้นเดียวกัน มิเช่นนั้นความเสียหายที่จุดนั้นจะกระทบทั้งสองเส้นทางพร้อมกัน ทำให้การมีเส้นทางสำรองไม่ได้ให้ประโยชน์ตามที่ตั้งใจไว้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบสื่อสารโทรคมนาคมจึงต้องพิจารณาความซ้ำซ้อนของเส้นทาง (Route Diversity) สำหรับการเชื่อมต่อที่สำคัญ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดคุณภาพของการบริการ (Quality of Service, QoS) จึงมีความสำคัญในระบบเครือข่ายที่ส่งข้อมูลหลายประเภทร่วมกัน เช่น เสียง วิดีโอ และข้อมูลทั่วไป', 'เพราะข้อมูลแต่ละประเภทมีความต้องการด้านคุณภาพการส่งที่แตกต่างกัน เช่น การสนทนาด้วยเสียงต้องการความหน่วงเวลาต่ำมากเพื่อการสนทนาที่ราบรื่น ในขณะที่การส่งไฟล์ข้อมูลทั่วไปสามารถทนความหน่วงเวลาได้มากกว่าโดยไม่กระทบการใช้งาน กลไก QoS ช่วยจัดลำดับความสำคัญของข้อมูลแต่ละประเภทให้ได้รับทรัพยากรเครือข่ายที่เหมาะสมกับความต้องการของตน', 'หากไม่มีการจัดการ QoS ที่เหมาะสม การส่งข้อมูลปริมาณมาก เช่น การดาวน์โหลดไฟล์ขนาดใหญ่ อาจแย่งใช้แบนด์วิดท์จนกระทบคุณภาพของการสนทนาด้วยเสียงหรือวิดีโอที่กำลังใช้งานพร้อมกันในเครือข่ายเดียวกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดคุณภาพของการบริการ (Quality of Service, QoS) จึงมีความสำคัญในระบบเครือข่ายที่ส่งข้อมูลหลายประเภทร่วมกัน เช่น เสียง วิดีโอ และข้อมูลทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งระบบสื่อสารในอาคารจึงต้องพิจารณาการเผื่อความจุสำรองสำหรับเทคโนโลยีในอนาคต แม้ในขณะออกแบบจะเพียงพอกับความต้องการปัจจุบันแล้วก็ตาม', 'เพราะเทคโนโลยีการสื่อสารมีการพัฒนาอย่างรวดเร็ว ความต้องการแบนด์วิดท์และความเร็วในการรับส่งข้อมูลมีแนวโน้มเพิ่มขึ้นอย่างต่อเนื่อง โครงสร้างพื้นฐานทางกายภาพ เช่น ท่อร้อยสายหรือเส้นทางเดินสาย มักมีอายุการใช้งานยาวนานกว่าอุปกรณ์อิเล็กทรอนิกส์มาก การเผื่อความจุตั้งแต่แรกช่วยลดต้นทุนและความยุ่งยากในการปรับปรุงโครงสร้างพื้นฐานในอนาคต', 'แนวปฏิบัติที่ดีมักแนะนำให้เผื่อขนาดท่อร้อยสายและจำนวนสายที่เดินไว้มากกว่าความต้องการปัจจุบันในสัดส่วนที่เหมาะสม เพื่อรองรับการอัปเกรดเทคโนโลยีในอนาคตโดยไม่ต้องรื้อโครงสร้างเดิมทั้งหมด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งระบบสื่อสารในอาคารจึงต้องพิจารณาการเผื่อความจุสำรองสำหรับเทคโนโลยีในอนาคต แม้ในขณะออกแบบจะเพียงพอกับความต้องการปัจจุบันแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการทดสอบและรับรองสายสัญญาณสื่อสาร (Cable Certification) หลังการติดตั้งจึงมีความสำคัญ แม้จะเลือกใช้สายเคเบิลที่มีคุณภาพตามมาตรฐานแล้วก็ตาม', 'เพราะประสิทธิภาพของสายสัญญาณไม่ได้ขึ้นอยู่กับคุณภาพของสายเคเบิลเพียงอย่างเดียว แต่ยังขึ้นอยู่กับการติดตั้งที่ถูกต้อง เช่น รัศมีการดัดโค้งที่เหมาะสม การเชื่อมต่อปลายสายที่ถูกวิธี และความยาวของสายที่ไม่เกินขีดจำกัด การทดสอบหลังการติดตั้งช่วยยืนยันว่าระบบทั้งหมดทำงานได้ตามมาตรฐานที่กำหนดจริง ไม่ใช่เพียงอาศัยคุณภาพของวัสดุที่ใช้เท่านั้น', 'การทดสอบทั่วไปมักครอบคลุมการวัดค่าต่างๆ เช่น การลดทอนสัญญาณ ความสามารถทนสัญญาณรบกวนข้ามสาย (Crosstalk) และความต่อเนื่องของสายทั้งเส้น เพื่อยืนยันว่าสายสัญญาณที่ติดตั้งสามารถรองรับความเร็วการสื่อสารที่ต้องการได้จริง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการทดสอบและรับรองสายสัญญาณสื่อสาร (Cable Certification) หลังการติดตั้งจึงมีความสำคัญ แม้จะเลือกใช้สายเคเบิลที่มีคุณภาพตามมาตรฐานแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดระบบสื่อสารที่ใช้ในงานความปลอดภัยหรืองานควบคุมสำคัญ จึงมักต้องการความน่าเชื่อถือสูงกว่าระบบสื่อสารเพื่อความบันเทิงทั่วไป', 'เพราะความล้มเหลวของระบบสื่อสารในงานความปลอดภัยหรืองานควบคุมสำคัญ เช่น ระบบแจ้งเหตุเพลิงไหม้หรือระบบควบคุมกระบวนการอุตสาหกรรม อาจนำไปสู่อันตรายต่อชีวิตหรือความเสียหายร้ายแรง ในขณะที่ความล้มเหลวชั่วคราวของระบบสื่อสารเพื่อความบันเทิง เช่น การรับชมวิดีโอสตรีมมิง อาจสร้างความรำคาญแต่ไม่ก่อให้เกิดอันตรายร้ายแรง', 'ระบบสื่อสารในงานสำคัญจึงมักออกแบบให้มีความซ้ำซ้อน (Redundancy) และมาตรการทดสอบความน่าเชื่อถือที่เข้มงวดกว่า แม้จะมีต้นทุนสูงกว่าระบบสื่อสารทั่วไปมาก เนื่องจากผลกระทบจากความล้มเหลวมีความรุนแรงต่างกันมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดระบบสื่อสารที่ใช้ในงานความปลอดภัยหรืองานควบคุมสำคัญ จึงมักต้องการความน่าเชื่อถือสูงกว่าระบบสื่อสารเพื่อความบันเทิงทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเลือกใช้ตัวกลางการสื่อสาร (Transmission Medium) ที่เหมาะสมสำหรับแต่ละสถานการณ์ จึงต้องพิจารณาปัจจัยหลายด้านร่วมกัน ไม่ใช่เพียงความเร็วในการส่งข้อมูลสูงสุดที่รองรับได้', 'เพราะแต่ละสถานการณ์มีข้อจำกัดและความต้องการที่แตกต่างกัน เช่น ต้นทุนการติดตั้ง ระยะทางที่ต้องการส่ง ความทนทานต่อสภาพแวดล้อม ความเสี่ยงจากสัญญาณรบกวน และความยากง่ายในการบำรุงรักษาซ่อมแซม ตัวกลางที่มีความเร็วสูงสุดอาจไม่ใช่ตัวเลือกที่คุ้มค่าหรือเหมาะสมที่สุดเสมอไปหากปัจจัยอื่นไม่สอดคล้องกับสถานการณ์นั้น', 'วิศวกรออกแบบระบบสื่อสารจึงต้องพิจารณาภาพรวมของความต้องการทั้งหมดของโครงการ แทนที่จะเลือกเทคโนโลยีเพียงเพราะมีตัวเลขความเร็วสูงสุดที่ดูดีที่สุดในทางทฤษฎี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเลือกใช้ตัวกลางการสื่อสาร (Transmission Medium) ที่เหมาะสมสำหรับแต่ละสถานการณ์ จึงต้องพิจารณาปัจจัยหลายด้านร่วมกัน ไม่ใช่เพียงความเร็วในการส่งข้อมูลสูงสุดที่รองรับได้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรไฟฟ้าสื่อสารจึงต้องมีความเข้าใจพื้นฐานทั้งด้านไฟฟ้ากำลังและด้านการสื่อสาร แม้จะเชี่ยวชาญเฉพาะทางด้านใดด้านหนึ่งเป็นหลัก', 'เพราะระบบสื่อสารในปัจจุบันมักเชื่อมโยงและติดตั้งอยู่ในสภาพแวดล้อมเดียวกันกับระบบไฟฟ้ากำลัง เช่น การติดตั้งสายสื่อสารในอาคารต้องพิจารณาผลกระทบจากสัญญาณรบกวนของระบบไฟฟ้ากำลังใกล้เคียง หรือระบบไฟฟ้าสำรองสำหรับอุปกรณ์สื่อสารที่สำคัญต้องออกแบบให้เชื่อถือได้เพียงพอ ความเข้าใจทั้งสองด้านช่วยให้ออกแบบระบบโดยรวมได้อย่างเหมาะสมและปลอดภัย', 'นี่เป็นเหตุผลสำคัญที่ในระบบใบอนุญาตวิชาชีพวิศวกรรมไฟฟ้าของไทย สาขาไฟฟ้ากำลังและไฟฟ้าสื่อสารยังคงถูกจัดอยู่ภายใต้สาขาวิชาชีพไฟฟ้าเดียวกัน แม้จะมีความเชี่ยวชาญเฉพาะทางที่แตกต่างกันในทางปฏิบัติ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรไฟฟ้าสื่อสารจึงต้องมีความเข้าใจพื้นฐานทั้งด้านไฟฟ้ากำลังและด้านการสื่อสาร แม้จะเชี่ยวชาญเฉพาะทางด้านใดด้านหนึ่งเป็นหลัก'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวางแผนพัฒนาระบบสื่อสารโทรคมนาคมในระดับประเทศ จึงต้องพิจารณาทั้งความต้องการปัจจุบันและแนวโน้มการเติบโตของการใช้งานข้อมูลในอนาคต', 'เพราะการก่อสร้างโครงสร้างพื้นฐานโทรคมนาคมขนาดใหญ่ เช่น สายเคเบิลใต้น้ำระหว่างประเทศหรือโครงข่ายเส้นใยแก้วนำแสงหลัก ใช้เวลาและเงินลงทุนสูงมาก และมีอายุการใช้งานยาวนาน หากวางแผนตามความต้องการปัจจุบันเพียงอย่างเดียวโดยไม่พิจารณาแนวโน้มการเติบโต อาจทำให้โครงสร้างพื้นฐานไม่เพียงพอต่อความต้องการในอนาคตอันใกล้ ซึ่งการขยายเพิ่มเติมภายหลังมักมีต้นทุนสูงกว่าการวางแผนเผื่อไว้ตั้งแต่แรก', 'แนวโน้มการเติบโตของการใช้งานข้อมูลในยุคปัจจุบันมีอัตราสูงมากจากปัจจัยต่างๆ เช่น การเพิ่มขึ้นของอุปกรณ์เชื่อมต่ออินเทอร์เน็ต การใช้งานวิดีโอความละเอียดสูง และการประยุกต์ใช้เทคโนโลยีใหม่ๆ ทำให้การวางแผนโครงสร้างพื้นฐานโทรคมนาคมต้องมีมุมมองระยะยาวที่ครอบคลุมมากกว่าความต้องการเฉพาะหน้าเพียงอย่างเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวางแผนพัฒนาระบบสื่อสารโทรคมนาคมในระดับประเทศ จึงต้องพิจารณาทั้งความต้องการปัจจุบันและแนวโน้มการเติบโตของการใช้งานข้อมูลในอนาคต'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'telecom_basics'
group by c.name_th;
